import {EboComponent} from "./EboComponent";
import {GuiSource} from "../events";
import {AllUris, Goto} from "../modelTypes";
import {EboButton} from "./general/eboButton";

export type ListButtonState = "show" | "hide" | "disabled";
export type ListButtonStates = {
    add: ListButtonState;
    play: ListButtonState;
    edit: ListButtonState;
    replace: ListButtonState;
    save: ListButtonState;
    new_playlist: ListButtonState;
    line_or_icon: ListButtonState;
}

export function getDefaultListButtonsState(states: ListButtonStates, defaultState: ListButtonState): ListButtonStates {
    states.add = defaultState;
    states.replace = defaultState;
    states.play = defaultState;
    states.save = defaultState;
    states.edit = defaultState;
    return states;
}


export type ListButtonName = keyof ListButtonStates;
export function ListButtonState_AllHidden(): ListButtonStates {
    return {
        add: "hide",
            play: "hide",
        edit: "hide",
        replace: "hide",
        save: "hide",
        new_playlist: "hide",
        line_or_icon: "hide"
    };
}

export class EboListButtonBar extends EboComponent {
    get btn_states(): ListButtonStates {
        return this._btn_states;
    }

    set btn_states(value: ListButtonStates) {
        this._btn_states = value;
        this.requestUpdate();
    }
    static override readonly tagName=  "ebo-list-button-bar";
    // noinspection JSUnusedGlobalSymbols
    static observedAttributes = ["list_source", "uri", "use_selected_color"];
    private _btn_states: ListButtonStates = ListButtonState_AllHidden();
    list_source: GuiSource = "albumView"; //todo: check if this default matters.
    uri: string = "";
    use_selected_color: boolean = false;
    static styleText = `
        <style>
            #buttons {
                display: flex;
                flex-direction: row;
                margin-bottom: .5em;
                button.disabled {
                    opacity: 0.2;
                }
                button.playButton {
                    background-color: var(--playing-background);
                    border: none;
                }
                img {
                    height: 1.2rem;
                }
                ebo-button {
                    height: 1.2rem;
                    width: 1.4rem;
                    position: relative;
                    top: .4rem;
                    margin-inline-start: .5rem;
                }
                button.selected {
                    background-color: var(--selected-background);
                }
            }
        </style>
    `;
    static htmlText = `
        <div id="buttons">
            <button id="btnPlay" class="roundBorder playButton iconButton"><i class="fa fa-play"></i></button>
            <button id="btnAdd" class="roundBorder playButton iconButton"><i class="fa fa-plus"></i></button>
            <button id="btnReplace" class="roundBorder playButton">Replace</button>
            <button id="btnEdit" class="roundBorder"><i class="fa fa-pencil"></i></button>
            <button id="btnSave" class="roundBorder">
                <div class="flexRow">
                    >            
                    <img id="bigImage" src="images/icons/Playlist.svg" alt="New playlist" class="whiteIcon">
                </div>            
            </button>
            <button id="btnNewPlaylist" class="roundBorder">
                <div class="flexRow">
                    <img id="bigImage" src="images/icons/Playlist.svg" alt="New playlist" class="whiteIcon">
                    *            
                </div>            
            </button>
            <ebo-button toggle id="btnDisplayMode" img="images/icons/IconView.svg" class="whiteIcon"></ebo-button>
        </div>                   
    `;

    constructor() {
        super(EboListButtonBar.styleText, EboListButtonBar.htmlText);
    }

    attributeReallyChangedCallback(name: string, _oldValue: string, newValue: string) {
        switch (name) {
            case "list_source":
                this.list_source = newValue as GuiSource;
                break;
            case "uri":
                this[name] = newValue;
                break;
            case "use_selected_color":
                this.updateBoolProperty(name, newValue);
        }
        this.requestUpdate();
        }

    override render(shadow:ShadowRoot) {
        this.addShadowEventListener("btnPlay", "click", () => {
            if(this.btn_states.play != "show") return;
            this.dispatchEboEvent("playItemClicked.eboplayer", {source: this.list_source});
        });
        this.addShadowEventListener("btnAdd", "click", () => {
            if(this.btn_states.add != "show") return;
            this.dispatchEboEvent("addItemListClicked.eboplayer", {source: this.list_source});
        });
        this.addShadowEventListener("btnReplace", "click", () => {
            if(this.btn_states.replace != "show") return;
            this.dispatchEboEvent("replaceItemListClicked.eboplayer", {source: this.list_source});
        });
        this.addShadowEventListener("btnEdit", "click", () => {
            if(this.btn_states.edit != "show") return;
            this.dispatchEboEvent("editClicked.eboplayer", {source: this.list_source});
        });
        this.addShadowEventListener("btnSave", "click", () => {
            if(this.btn_states.save != "show") return;
            this.dispatchEboEvent("saveToPlaylistClicked.eboplayer", {source: this.list_source, uri: this.uri as AllUris});
        });
        this.addShadowEventListener("btnNewPlaylist", "click", () => {
            if(this.btn_states.new_playlist != "show") return;
            this.dispatchEboEvent("newPlaylistClicked.eboplayer", {source: this.list_source});
        });
        let btnDisplayMode = this.shadow.getElementById("btnDisplayMode") as EboButton;
        btnDisplayMode.on("pressedChange.eboplayer", (ev) => {
           this.dispatchEboEvent("displayModeChanged.eboplayer", {mode: ev.detail.pressed ? "icon" : "line"});
        });
        this.requestUpdate();
    }

    override update(shadow: ShadowRoot) {
        this.updateButtonVisibility("btnPlay", this._btn_states.play);
        this.updateButtonVisibility("btnAdd", this._btn_states.add);
        this.updateButtonVisibility("btnReplace", this._btn_states.replace);
        this.updateButtonVisibility("btnEdit", this._btn_states.edit);
        this.updateButtonVisibility("btnSave", this._btn_states.save);
        this.updateButtonVisibility("btnNewPlaylist", this._btn_states.new_playlist);
        this.updateButtonVisibility("btnDisplayMode", this._btn_states.line_or_icon);
        let playButtons = shadow.querySelectorAll("button.playButton");
        playButtons.forEach(button => {
            button.classList.toggle("selected", this.use_selected_color);
        });
    }

    private updateButtonVisibility(id: string, state: ListButtonState) {
        let btn = this.shadow.getElementById(id) as HTMLButtonElement;
        switch (state) {
            case "show": btn.style.display = ""; break;
            case "hide": btn.style.display = "none"; break;
            case "disabled":
                btn.disabled = true;
                btn.classList.add("disabled");
                break;
            default:
                break;//no state specified: ignore
        }
    }
}